	private static final String RESTRICTION = "test.scanSelection";
	private static final PackedStatementPatternSemanticsCodec CODEC = codec(1);

	@Test
	void canonicalPrimitiveContentOwnsItsWordsAndUsesExactEquality() {
		long[] input = { 7L, 11L };
		var value = new PackedStatementPatternSemanticsCodec.Content(input);
		input[0] = 19L;
		assertEquals(7L, value.word(0));
		assertEquals(value, new PackedStatementPatternSemanticsCodec.Content(7L, 11L));
		assertNotEquals(value, new PackedStatementPatternSemanticsCodec.Content(7L, 19L));
	}

	@Test
	void capturesBeforeTermPoolingAndRestoresAfterAllAdvisoryMetadata() {
		StatementPattern restricted = pattern(1L);
		restricted.getObjectVar().setStringMetricPlanned(RESTRICTION, "pooled-term");
		var query = PackedQueryCodec.encodeForPlanning(new Join(restricted, pattern(2L)), null, CODEC);
		int left = query.relChild(query.rootRelId(), 0);
		int right = query.relChild(query.rootRelId(), 1);
		assertNotEquals(query.relGroup(left), query.relGroup(right));
		List<StatementPattern> result = patterns(PackedPlanMaterializer.materialize(query, query.rootRelId()));
		assertEquals(List.of("1", "2"), result.stream().map(p -> p.getStringMetricPlanned(RESTRICTION)).toList());
		for (var statement : result) {
			assertNull(statement.getObjectVar().getStringMetricPlanned(RESTRICTION));
		}
	}

	@Test
	void unrestrictedOccurrenceCannotInheritPooledRestriction() {
		StatementPattern restricted = pattern(1L);
		restricted.getObjectVar().setStringMetricPlanned(RESTRICTION, "pooled-term");
		var query = PackedQueryCodec.encodeForPlanning(new Union(restricted, pattern(0L)), null, CODEC);
		List<StatementPattern> result = patterns(PackedPlanMaterializer.materialize(query, query.rootRelId()));
		assertEquals("1", result.getFirst().getStringMetricPlanned(RESTRICTION));
		assertNull(result.getLast().getStringMetricPlanned(RESTRICTION));
		assertNull(result.getLast().getObjectVar().getStringMetricPlanned(RESTRICTION));
	}

	@Test
	void annotationFreeIdentityAndFamilyCarryContentAndSchema() {
		var one = PackedQueryCacheIdentity.createPlanIdentity(pattern(1L), null, CODEC);
		var two = PackedQueryCacheIdentity.createPlanIdentity(pattern(2L), null, CODEC);
		assertFalse(one.matches(two));
		assertTrue(one.matches(PackedQueryCacheIdentity.createPlanIdentity(pattern(1L), null, CODEC)));
		assertFalse(PackedQueryCacheIdentity.createPlanIdentity(pattern(0L), null, CODEC)
				.matches(PackedQueryCacheIdentity.createPlanIdentity(pattern(0L), null, codec(2))));
		assertFalse(PackedQueryFamilyIdentity.create(pattern(1L), null, CODEC)
				.matches(PackedQueryFamilyIdentity.create(pattern(2L), null, CODEC)));
		var family = PackedQueryFamilyIdentity.create(pattern(1L), null, CODEC);
		assertTrue(PackedQueryFamilyIdentity.sameConcreteInvocation(family,
				PackedQueryFamilyIdentity.create(pattern(1L), null, CODEC)));
		assertTrue(family.parameterizedQueryTemplate()
				.hasSameCacheIdentity(
						family.parameterizedQueryTemplate()
								.withoutOriginalBindingSets()
								.withoutInvocationParameters()));
	}

	@Test
	void completeStructuralCacheKeyIncludesSemanticsBeforePlanning() {
		assertNotEquals(PackedPlanCache.structuralKey(pattern(1L), CODEC),
				PackedPlanCache.structuralKey(pattern(2L), CODEC));
		assertEquals(PackedPlanCache.structuralKey(pattern(1L), CODEC),
				PackedPlanCache.structuralKey(pattern(1L).clone(), CODEC));
		assertNotEquals(PackedPlanCache.structuralKey(pattern(0L), CODEC),
				PackedPlanCache.structuralKey(pattern(0L)));
	}

	@Test
	void recipeAndContinuationRetainTheStatelessCodecAndExactContent() {
		var query = PackedQueryCodec.encodeForPlanning(pattern(1L), null, CODEC);
		PackedMemo memo = new PackedMemo(query, 8, 2, 2, 4, 4, 8);
		int group = query.relGroup(query.rootRelId());
		int any = memo.anyPropertyId();
		int physical = memo.addPhysicalAlternative(group, PackedRelOp.STATEMENT_PATTERN,
				query.relPayload(query.rootRelId()), any, 1, new int[0], 0, 0);
		int winner = memo.offerWinner(group, any, 0, 0, 0, physical, 1.0d, 1.0d, 1.0d, new int[0], 0, 0);
		var recipe = memo.extractPlanRecipe(winner);
		TupleExpr result = PackedPlanMaterializer.materialize(query, recipe);
		assertEquals("1", patterns(result).getFirst().getStringMetricPlanned(RESTRICTION));
		assertFalse(recipe.physicalIdentity(result).sameExecutablePlan(recipe.physicalIdentity(pattern(2L))));
		assertTrue(recipe.physicalIdentity(result).sameExecutablePlan(recipe.physicalIdentity(result.clone())));
		assertEquals("1", patterns(PackedPlanMaterializer.materialize(query, recipe.withoutDetachedEvidence()))
				.getFirst()
				.getStringMetricPlanned(RESTRICTION));
	}

