	@Test
	void encodeCapturesVariableOverrideBeforeInputFrameNormalizerCopiesTheSource() {
		StatementPattern source = pattern(1L);
		source.getObjectVar().setStringMetricPlanned(RESTRICTION, "2");
		var query = PackedQueryCodec.encodeForPlanning(source, null, codec(1, true));
		assertEquals("2", patterns(PackedPlanMaterializer.materialize(query, query.rootRelId()))
				.getFirst()
				.getStringMetricPlanned(RESTRICTION));
		assertEquals("1", source.getStringMetricPlanned(RESTRICTION));
		assertEquals("2", source.getObjectVar().getStringMetricPlanned(RESTRICTION));
	}

	@Test
	void detachedRefreshCopiesCaptureVariableOverridesBeforeGenericClone() {
		var variableCodec = codec(1, true);
		StatementPattern source = pattern(1L);
		source.getObjectVar().setStringMetricPlanned(RESTRICTION, "2");
		var goal = OptimizationGoal.root();
		var incumbent = PackedCascadesPlanner.optimize(source, goal, null, null, variableCodec);
		var work = PackedCascadesPlanner.detachedRefreshWork(source, goal, incumbent.decisionSummary(), variableCodec)
				.orElseThrow();
		assertTrue(work.authenticates(work.preparedSource()),
				"the detached copy must preserve the occurrence captured by its locator");
		assertEquals("2", patterns(work.preparedSource()).getFirst().getStringMetricPlanned(RESTRICTION));
		assertEquals("2", source.getObjectVar().getStringMetricPlanned(RESTRICTION));
		assertEquals("1", source.getStringMetricPlanned(RESTRICTION), "copying must leave the caller untouched");
	}

	@Test
	void semanticCopierClonesOnceAndPreservesNestedOccurrencesWithoutChangingSource() {
		StatementPattern overridden = pattern(1L);
		overridden.getObjectVar().setStringMetricPlanned(RESTRICTION, "2");
		StatementPattern empty = pattern(0L);
		StatementPattern nested = new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:selection")), Var.of("o"),
				Var.of("g"));
		nested.setStringMetricPlanned(RESTRICTION, "1");
		nested.setIndependentInputScope(true);
		nested.setContextBindingOriginInherited(true);
		assertTrue(nested.isContextBindingOriginInherited());
		CountingUnion source = new CountingUnion(new LeftJoin(overridden, empty),
				new Filter(pattern(0L), new Exists(nested)));
		TupleExpr copied = codec(1, true).cloneWithSemantics(source);
		assertEquals(1, source.clones.get());
		assertEquals(java.util.Arrays.asList("2", null, "1", null), patterns(copied).stream()
				.map(p -> p.getStringMetricPlanned(RESTRICTION))
				.toList());
		assertTrue(patterns(copied).get(2).isIndependentInputScope());
		assertTrue(patterns(copied).get(2).isContextBindingOriginInherited());
		assertEquals("1", overridden.getStringMetricPlanned(RESTRICTION));
		assertEquals("2", overridden.getObjectVar().getStringMetricPlanned(RESTRICTION));
		assertNull(empty.getStringMetricPlanned(RESTRICTION));
	}

