	private static final class CountingUnion extends Union {
		private final AtomicInteger clones = new AtomicInteger();

		private CountingUnion(TupleExpr left, TupleExpr right) {
			super(left, right);
		}

		@Override
		public CountingUnion clone() {
			clones.incrementAndGet();
			return (CountingUnion) super.clone();
		}
	}

	private static StatementPattern pattern(long code) {
		StatementPattern result = new StatementPattern(Var.of("s"),
				Var.of("p", SimpleValueFactory.getInstance().createIRI("urn:test:selection")), Var.of("o"));
		if (code != 0L) {
			result.setStringMetricPlanned(RESTRICTION, Long.toString(code));
		}
		return result;
	}

	private static List<StatementPattern> patterns(TupleExpr expression) {
		List<StatementPattern> result = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				result.add(pattern);
			}
		});
		return result;
	}

	private static PackedStatementPatternSemanticsCodec codec(int version) {
		return codec(version, false);
	}

	private static PackedStatementPatternSemanticsCodec codec(int version, boolean variableOverride) {
		return new PackedStatementPatternSemanticsCodec() {
			@Override
			public String schemaId() {
				return "test-pure-row-selection" + (variableOverride ? "-variable" : "");
			}

			@Override
			public int schemaVersion() {
				return version;
			}

			@Override
			public Content capture(StatementPattern source) {
				String code = source.getStringMetricPlanned(RESTRICTION);
				if (variableOverride && source.getObjectVar().getStringMetricPlanned(RESTRICTION) != null) {
					code = source.getObjectVar().getStringMetricPlanned(RESTRICTION);
				}
				return new Content(code == null ? 0L : Long.parseLong(code));
			}

			@Override
			public void restore(StatementPattern target, Content content) {
				target.removeStringMetricsPlannedIf(RESTRICTION::equals);
				for (Var term : List.of(target.getSubjectVar(), target.getPredicateVar(), target.getObjectVar())) {
					term.removeStringMetricsPlannedIf(RESTRICTION::equals);
				}
				if (content.word(0) != 0L) {
					target.setStringMetricPlanned(RESTRICTION, Long.toString(content.word(0)));
				}
			}
		};
	}
